  /* ========================= PHÂN PHỐI / BLOG / INTRO ========================= */
  "Unifarm trên toàn quốc": { en: "Unifarm Nationwide", ja: "全国のUnifarm", ko: "전국의 Unifarm", "zh-TW": "Unifarm 遍佈全國" },
  "Tìm cửa hàng Unifarm gần bạn nhất — nông sản sạch, an toàn, chuẩn truy xuất nguồn gốc, sẵn sàng phục vụ mỗi ngày.": { en: "Find the nearest Unifarm store — clean, safe farm produce with verified traceability, ready to serve you every day.", ja: "最寄りのUnifarm店舗を検索 — 安全で新鮮、トレーサビリティ認証済みの農産物を毎日ご提供します。", ko: "가까운 Unifarm 매장을 찾아보세요 — 안전하고 깨끗하며 원산지 추적이 가능한 농산물을 매일 제공합니다.", "zh-TW": "尋找離您最近的Unifarm門市——潔淨安全、可溯源認證的優質農產品，每日隨時為您服務。" },
  "Bài viết": { en: "Articles", ja: "記事", ko: "게시물", "zh-TW": "文章" },
  "Lượt đọc": { en: "Views", ja: "閲覧数", ko: "조회수", "zh-TW": "瀏覽次數" },
  "Tăng trưởng": { en: "Growth", ja: "成長率", ko: "성장률", "zh-TW": "增長率" },
  "Tri thức Unifarm": { en: "Unifarm Knowledge", ja: "Unifarmの知見", ko: "Unifarm 지식", "zh-TW": "Unifarm 知識專欄" },
  "Tri Thức Chỉ Thực Sự Lớn Lên Khi Được Chia Sẻ": { en: "Knowledge Only Truly Grows When It Is Shared", ja: "知識は共有されてこそ、真に育つ", ko: "지식은 나눌 때 비로소 진정으로 성장합니다", "zh-TW": "知識唯有分享，方能真正成長" },
  "Mỗi ngày ngoài cánh đồng đều đặt ra những bài toán mới. Unifarm không giữ tri thức cho riêng mình. Đây là nơi chúng tôi đóng góp cho nền nông nghiệp bằng việc chia sẻ minh bạch những gì đúc kết được từ thử nghiệm thực địa và dữ liệu sản xuất.": { en: "Every day out in the fields raises new questions. Unifarm doesn't keep its knowledge to itself. This is where we give back to agriculture by transparently sharing what we've learned from field trials and production data.", ja: "畑では毎日、新たな課題が生まれます。Unifarmは知識を独り占めしません。ここは、実地試験と生産データから得た知見を透明に共有することで、農業に貢献する場所です。", ko: "매일 농장에서는 새로운 과제가 생겨납니다. Unifarm은 지식을 독점하지 않습니다. 이곳은 현장 실험과 생산 데이터에서 얻은 결과를 투명하게 공유함으로써 농업 발전에 기여하는 공간입니다.", "zh-TW": "田野間每天都會出現新的課題。Unifarm不會將知識據為己有。這裡是我們透過公開分享田間試驗與生產數據所得心得，回饋農業的地方。" },
